//! Ruby extension for `lib/shellwords.rb`, generated by everything-rust from `src/port.rs`. Regenerate with
//! `everything-rust refresh`. Values convert directly between Ruby and Rust: no JSON.

use magnus::{Error, ExceptionClass, Module, Object, Ruby, function, method};
#[allow(unused_imports)]
use serde_json::Value;

pub mod port;

/// Batches allocate on all cores at once; mimalloc keeps that from serializing.
#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

mod rbconv;

/// `Err("ArgumentError: message")` raises that exception class; otherwise a RuntimeError.
fn error(ruby: &Ruby, message: String) -> Error {
    if let Some((kind, text)) = message.split_once(": ")
        && kind.starts_with(|c: char| c.is_ascii_uppercase())
        && kind.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
        && let Ok(class) = ruby.class_object().const_get::<_, ExceptionClass>(kind)
    {
        return Error::new(class, text.to_string());
    }
    Error::new(ruby.exception_runtime_error(), message)
}

/// Runs the port; a panic becomes a RuntimeError instead of Ruby's uncatchable `fatal`.
fn guard<T>(ruby: &Ruby, f: impl FnOnce() -> Result<T, String>) -> Result<T, Error> {
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(f)) {
        Ok(result) => result.map_err(|m| error(ruby, m)),
        Err(panic) => {
            let text = panic
                .downcast_ref::<&str>()
                .map(ToString::to_string)
                .or_else(|| panic.downcast_ref::<String>().cloned())
                .unwrap_or_default();
            Err(Error::new(
                ruby.exception_runtime_error(),
                format!("Rust panic: {text}"),
            ))
        }
    }
}

/// `shellsplit`.
fn rb_shellsplit(ruby: &Ruby, line: magnus::Value) -> Result<magnus::Value, Error> {
    let line: Value = rbconv::arg(line).map_err(|m| error(ruby, m))?;
    guard(ruby, || port::shellsplit(line)).and_then(|out| rbconv::to_rb(ruby, &out))
}

/// `shellescape`.
fn rb_shellescape(ruby: &Ruby, str: magnus::Value) -> Result<magnus::Value, Error> {
    let str: Value = rbconv::arg(str).map_err(|m| error(ruby, m))?;
    guard(ruby, || port::shellescape(str)).and_then(|out| rbconv::to_rb(ruby, &out))
}

/// `shelljoin`.
fn rb_shelljoin(ruby: &Ruby, array: magnus::Value) -> Result<magnus::Value, Error> {
    let array: Value = rbconv::arg(array).map_err(|m| error(ruby, m))?;
    guard(ruby, || port::shelljoin(array)).and_then(|out| rbconv::to_rb(ruby, &out))
}

/// The items of `ShellescapeBatch` as the port takes them; the port runs per item. Define
/// `pub struct ShellescapeIndex` in `port.rs` (with `new` and `run`) to prepare items once.
pub struct ShellescapeDefaultIndex {
    items: Vec<Value>,
}

impl ShellescapeDefaultIndex {
    pub fn new(items: Vec<Value>) -> Self {
        Self { items }
    }

    pub fn run(&self) -> Result<Vec<Value>, String> {
        use rayon::prelude::*;
        self.items
            .par_iter()
            .map(|item| port::shellescape(item.clone()))
            .collect::<Vec<_>>()
            .into_iter()
            .collect()
    }
}

/// `shellescape` over many `str` values kept in Rust: `run` maps them all in one call, on
/// all cores; `rank` returns the indexes of results >= `min`, best first.
#[magnus::wrap(
    class = "EverythingRustNativeShellwordsRs::ShellescapeBatch",
    free_immediately,
    size
)]
pub struct ShellescapeBatch {
    inner: ShellescapeDefaultIndex,
}

impl ShellescapeBatch {
    fn new(ruby: &Ruby, items: magnus::RArray) -> Result<Self, Error> {
        let items = (0..items.len())
            .map(|i| {
                rbconv::from_rb(
                    items
                        .entry(isize::try_from(i).unwrap_or(isize::MAX))
                        .map_err(|e| e.to_string())?,
                )
            })
            .collect::<Result<Vec<_>, _>>()
            .map_err(|m| error(ruby, m))?;
        guard(ruby, || {
            Ok(Self {
                inner: ShellescapeDefaultIndex::new(items),
            })
        })
    }

    fn run(ruby: &Ruby, rb_self: &Self) -> Result<magnus::RArray, Error> {
        guard(ruby, || rb_self.inner.run()).and_then(|out| {
            let array = ruby.ary_new_capa(out.len());
            for v in &out {
                array.push(rbconv::to_rb(ruby, v)?)?;
            }
            Ok(array)
        })
    }
}

#[magnus::init(name = "shellwords_rs_native")]
fn init(ruby: &Ruby) -> Result<(), Error> {
    let native = ruby.define_module("EverythingRustNativeShellwordsRs")?;
    native.define_module_function("shellsplit", function!(rb_shellsplit, 1))?;
    native.define_module_function("shellescape", function!(rb_shellescape, 1))?;
    native.define_module_function("shelljoin", function!(rb_shelljoin, 1))?;
    let class = native.define_class("ShellescapeBatch", ruby.class_object())?;
    class.define_singleton_method("new", function!(ShellescapeBatch::new, 1))?;
    class.define_method("run", method!(ShellescapeBatch::run, 0))?;
    Ok(())
}
